refentry.refsect1:
&reftitle.description;
mixedfilter_var mixedvalue intfilterFILTER_DEFAULT arrayintoptions0
検証フィルタ FILTER_VALIDATE_* や、除去フィルタ FILTER_SANITIZE_*、 またはカスタムフィルタを使って変数をフィルタリングします。

  &reftitle.examples;

   filter_var の例


<?php
var_dump(filter_var('bob@example.com', FILTER_VALIDATE_EMAIL));
var_dump(filter_var('https://example.com', FILTER_VALIDATE_URL, FILTER_FLAG_PATH_REQUIRED));
?>


   &example.outputs;


string(15) "bob@example.com"
bool(false)





    配列をフィルタする例


<?php
$emails = [
    "bob@example.com",
    "test@example.local",
    "invalidemail"
];

var_dump(filter_var($emails, FILTER_VALIDATE_EMAIL, FILTER_REQUIRE_ARRAY));
?>


   &example.outputs;


array(3) {
  [0]=>
  string(15) "bob@example.com"
  [1]=>
  string(18) "test@example.local"
  [2]=>
  bool(false)
}





   options に配列を渡す例


<?php

$options = [
    'options' => [
        'min_range' => 10,
    ],
    'flags' => FILTER_FLAG_ALLOW_OCTAL,
];

var_dump(filter_var('0755', FILTER_VALIDATE_INT, $options));
var_dump(filter_var('011', FILTER_VALIDATE_INT, $options));

?>


   &example.outputs;


int(493)
bool(false)





   配列経由、または直接フラグを渡す例


<?php

$str = 'string';

var_dump(filter_var($str, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE));
var_dump(filter_var($str, FILTER_VALIDATE_BOOLEAN, ['flags' => FILTER_NULL_ON_FAILURE]));

?>


   &example.outputs;


NULL
NULL





   検証結果を正しく確認する例


<?php

$value = '0';

// 間違い: 0 は有効な整数だが、false とみなされる
if (!filter_var($value, FILTER_VALIDATE_INT)) {
    echo "Wrong check: '$value' rejected\n";
}

// 正しい: false と厳密に比較する
if (filter_var($value, FILTER_VALIDATE_INT) === false) {
    echo "'$value' is not a valid integer\n";
} else {
    echo "'$value' is a valid integer\n";
}

?>


   &example.outputs;


Wrong check: '0' rejected
'0' is a valid integer





   boolean の検証結果を確認する例


<?php

foreach (['yes', 'no', 'maybe'] as $value) {
    $result = filter_var($value, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE);

    // ここでは false も有効な結果なので、null かどうかで判定する
    if ($result === null) {
        echo "'$value' is not a valid boolean\n";
    } else {
        echo "'$value' is ", var_export($result, true), "\n";
    }
}

?>


   &example.outputs;


'yes' is true
'no' is false
'maybe' is not a valid boolean
